import{_ as d,o as e,c as a,a2 as r}from"./chunks/framework.Cm6XCzck.js";const p=JSON.parse('{"title":"4. 已执行测试基线","description":"","frontmatter":{},"headers":[],"relativePath":"zh/publications/implementation-case-i0.8/part-02.md","filePath":"zh/publications/implementation-case-i0.8/part-02.md","lastUpdated":1786339128000}'),i={name:"zh/publications/implementation-case-i0.8/part-02.md"};function l(o,t,n,s,h,c){return e(),a("div",null,[...t[0]||(t[0]=[r(`<h1 id="_4-已执行测试基线" tabindex="-1">4. 已执行测试基线 <a class="header-anchor" href="#_4-已执行测试基线" aria-label="Permalink to &quot;4. 已执行测试基线&quot;">​</a></h1><p>主要产品运行与全量套件均由作者在固定输入上执行。跳过项保持为跳过项。</p><table tabindex="0"><thead><tr><th>轨道</th><th style="text-align:right;">结果</th><th style="text-align:right;">Exit</th><th>解释</th></tr></thead><tbody><tr><td>S0.6 产品 C01–C14</td><td style="text-align:right;">14 PASS / 0 FAIL / 0 PARTIAL / 0 NOT RUN</td><td style="text-align:right;">0</td><td>直接执行 CodeFlowMu 产品 Reader</td></tr><tr><td>CodeFlowMu 内置 TMPA</td><td style="text-align:right;">23/23</td><td style="text-align:right;">0</td><td>包含显式 S0.5 兼容与 S0.6 回归</td></tr><tr><td>CodeFlowMu Protocol</td><td style="text-align:right;">5 个有效 + 3 个预期无效 Fixture</td><td style="text-align:right;">0</td><td>产品协议测试，与 TMPA 裁决分开</td></tr><tr><td>Protocol / Runtime / Shell Typecheck</td><td style="text-align:right;">全部通过</td><td style="text-align:right;">0</td><td>仅静态检查</td></tr><tr><td>CodeFlowMu Runtime</td><td style="text-align:right;">1,485 passed、0 failed、1 skipped</td><td style="text-align:right;">0</td><td>作者本地完整 Runtime 运行</td></tr><tr><td>CodeFlowMu Shell</td><td style="text-align:right;">777 passed、0 failed</td><td style="text-align:right;">0</td><td>作者本地完整 Shell 运行</td></tr><tr><td>FCoP 锁定参考基线</td><td style="text-align:right;">1,210 passed、2 skipped</td><td style="text-align:right;">0</td><td>参考实现，不是协议证明</td></tr><tr><td>公开复现器</td><td style="text-align:right;"><code>npm ci</code> + 产品 14/14 PASS</td><td style="text-align:right;">0</td><td>自包含符合性切片复跑</td></tr></tbody></table><p>最终 Conformance Result 通过 S0.6 结果 Schema，记录 <code>product_reader_called: true</code>、<code>reference_reader_called: false</code>、实现 <code>codeflowmu/V1.6.0</code>，证据层级为 <code>demonstrated</code>。</p><h1 id="_5-c01–c14-产品结果" tabindex="-1">5. C01–C14 产品结果 <a class="header-anchor" href="#_5-c01–c14-产品结果" aria-label="Permalink to &quot;5. C01–C14 产品结果&quot;">​</a></h1><table tabindex="0"><thead><tr><th>ID</th><th>S0.6 准则</th><th style="text-align:right;">裁决</th><th>执行观察</th></tr></thead><tbody><tr><td>C01</td><td>Schema 验证</td><td style="text-align:right;"><strong>PASS</strong></td><td>四份正式 S0.6 Schema 全部编译；错误结构与声明 <code>date-time</code> 的负向案例被确定性拒绝。</td></tr><tr><td>C02</td><td>主载体与不可变性</td><td style="text-align:right;"><strong>PASS</strong></td><td>内容寻址修订保持可归责；主载体冲突不能取得权威；更正仍是独立证据。</td></tr><tr><td>C03</td><td>重复身份与来源</td><td style="text-align:right;"><strong>PASS</strong></td><td>同 ID 异内容被隔离；字节相同的观测投影为一个节点，同时保留全部确定排序的 <code>source_id</code>。</td></tr><tr><td>C04</td><td>串行连续性与异步推进</td><td style="text-align:right;"><strong>PASS</strong></td><td>流缺口与重号持续可见；无关流可以推进；到达顺序不改变输出。</td></tr><tr><td>C05</td><td>角色权威</td><td style="text-align:right;"><strong>PASS</strong></td><td>权限拒绝与权限不确定分支保持分离，且不能修改重建状态。</td></tr><tr><td>C06</td><td>生命周期合法性</td><td style="text-align:right;"><strong>PASS</strong></td><td>非法迁移被拒绝；缺少独立验收时完成保持不确定且不能推进。</td></tr><tr><td>C07</td><td>职责分离与人工批准</td><td style="text-align:right;"><strong>PASS</strong></td><td>错误批准类型、缺少 Assignment、不允许角色、缺少批准决定和自我批准均保持 <code>pending_human</code>；有效的已分配独立批准可以清除门禁。</td></tr><tr><td>C08</td><td>完整性篡改</td><td style="text-align:right;"><strong>PASS</strong></td><td>被覆盖内容篡改产生 <code>INTEGRITY_MISMATCH</code>，对象退出权威节点，失败来源仍被保留。</td></tr><tr><td>C09</td><td>缺失引用</td><td style="text-align:right;"><strong>PASS</strong></td><td>缺失依赖与主张证据保持可见并传播不确定结果，不虚构事实。</td></tr><tr><td>C10</td><td>禁止引用环</td><td style="text-align:right;"><strong>PASS</strong></td><td>只隔离受影响的禁止环子图，无关有效节点仍可使用。</td></tr><tr><td>C11</td><td>确定性重建</td><td style="text-align:right;"><strong>PASS</strong></td><td>固定来源排列产生字节等价结果；规范顺序采用 Unicode 码点顺序，包括 U+E000 在 U+10000 之前。</td></tr><tr><td>C12</td><td>冲突保留</td><td style="text-align:right;"><strong>PASS</strong></td><td>矛盾复核保持 disputed，直到授权解决者行动；未授权裁决保留为证据但不能清除冲突。</td></tr><tr><td>C13</td><td>恢复</td><td style="text-align:right;"><strong>PASS</strong></td><td>全新 Reader 能一致重建生命周期、责任、依赖、失败、恢复动作与父子状态。</td></tr><tr><td>C14</td><td>终态历史保留</td><td style="text-align:right;"><strong>PASS</strong></td><td>只有已验收授权链进入 archive，之前的任务、报告、复核和迁移历史仍可重建。</td></tr></tbody></table><h1 id="_6-s0-5-→-s0-6-产品差异" tabindex="-1">6. S0.5 → S0.6 产品差异 <a class="header-anchor" href="#_6-s0-5-→-s0-6-产品差异" aria-label="Permalink to &quot;6. S0.5 → S0.6 产品差异&quot;">​</a></h1><h2 id="_6-1-c03——聚合不丢失来源" tabindex="-1">6.1 C03——聚合不丢失来源 <a class="header-anchor" href="#_6-1-c03——聚合不丢失来源" aria-label="Permalink to &quot;6.1 C03——聚合不丢失来源&quot;">​</a></h2><p>I0.7 已演示同 ID 异内容候选的冲突处理。S0.6 增加第二条边界：多个字节相同的观测不能生成重复节点，但聚合也不能抹除观测来源。V1.6.0 输出一个规范节点和完整、按码点排序的 <code>source_ids</code> 列表。</p><h2 id="_6-2-c07——批准是授权治理对象" tabindex="-1">6.2 C07——批准是授权治理对象 <a class="header-anchor" href="#_6-2-c07——批准是授权治理对象" aria-label="Permalink to &quot;6.2 C07——批准是授权治理对象&quot;">​</a></h2><p>S0.5 基线已演示角色分离与高风险人工门禁。S0.6 让授权合同可以直接测试：只有对象类型被允许、行为者具有匹配 Assignment、角色被允许、正文包含批准决定，并且 Profile 要求时行为者相互独立，批准才成立。四个负向分支继续等待，不会被当作隐式批准。</p><h2 id="_6-3-c11——确定性意味着不依赖-locale" tabindex="-1">6.3 C11——确定性意味着不依赖 Locale <a class="header-anchor" href="#_6-3-c11——确定性意味着不依赖-locale" aria-label="Permalink to &quot;6.3 C11——确定性意味着不依赖 Locale&quot;">​</a></h2><p>S0.6 消除规范排序中的环境歧义。V1.6.0 在对象 Key、来源、图遍历、问题与输出集合中统一采用 Unicode 码点顺序。U+E000/U+10000 Fixture 可以识别普通 ASCII 测试无法发现的 UTF-16 Code Unit 排序错误。</p><h2 id="_6-4-兼容边界" tabindex="-1">6.4 兼容边界 <a class="header-anchor" href="#_6-4-兼容边界" aria-label="Permalink to &quot;6.4 兼容边界&quot;">​</a></h2><p>CodeFlowMu 内置套件包含显式 S0.5/I0.7 兼容路径。I0.7 继续作为精确的 S0.5 历史产品结果；I0.8 不改写其输入、准则、产品版本或证据包。</p><h1 id="_7-公开复现器" tabindex="-1">7. 公开复现器 <a class="header-anchor" href="#_7-公开复现器" aria-label="Permalink to &quot;7. 公开复现器&quot;">​</a></h1><p>正式压缩包包含 29 文件的自包含复现器，其中包括 Package Lock、产品 Reader、Protocol Validator、Profile、Fixtures、Runner 与正式输入。要求 Node.js 22 或更新版本以及公共 npm Registry：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cd public-reproducer</span></span>
<span class="line"><span>npm ci</span></span>
<span class="line"><span>npm test</span></span></code></pre></div><p>测试首先核验七个上游 SHA-256，然后调用打包的 CodeFlowMu <code>GovernanceReader</code>。记录的干净副本运行和出版预检均得到 14 PASS / 0 FAIL。该复现器让符合性切片可以公开检查，但不表示私有母体仓库或完整应用已经公开。</p><h1 id="_8-保留的-wp-13-证据门禁案例" tabindex="-1">8. 保留的 WP-13 证据门禁案例 <a class="header-anchor" href="#_8-保留的-wp-13-证据门禁案例" aria-label="Permalink to &quot;8. 保留的 WP-13 证据门禁案例&quot;">​</a></h1><p>WP-13 对工程解释仍有价值，但 I0.8 没有重新执行它。该案例记录了角色分离工作流：带完成含义的声明被暂停，直到持久证据、正式报告与 QA 验证建立。后续 Gate C 裁决接受交付，而 Active、Push/发布与 Archive 仍是独立决定。</p><p>该案例支持证据门禁、分阶段权威与同任务恢复，不证明幻觉消除、普遍错误声明检测或 S0.6 符合性。C01–C14 结果来自 V1.6.0 产品 Bundle，不来自 WP-13。</p>`,22)])])}const S=d(i,[["render",l]]);export{p as __pageData,S as default};
